import{z as A,x as d,o as E,c as B,q as o,j as l,D as e,d as r,s as i,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"可证明安全与归约","description":"","frontmatter":{"title":"可证明安全与归约","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/provable-security-reduction.md","filePath":"cs/provable-security-reduction.md","lastUpdated":1791413859000}'),p={name:"cs/provable-security-reduction.md"};function c(m,a,D,h,u,C){const t=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=o('<h1 id="可证明安全与归约" tabindex="-1">可证明安全与归约 <a class="header-anchor" href="#可证明安全与归约" aria-label="Permalink to &quot;可证明安全与归约&quot;">​</a></h1><div class="epigraph"><p>证明不是「没人破过」，而是：若敌手能赢这个游戏，就能构造算法赢那个被认为难的问题。归约把产品安全感绑到假设上；假设外的误用，证明沉默。</p><footer>—— Goldwasser and Micali, Probabilistic Encryption, 1984；Bellare and Rogaway 的游戏化方法；Katz and Lindell</footer></div><p>上一课<a href="/cs/homomorphic-intuition">同态</a>把电路评在密文上。本单元从一次一密走到外包计算，缺口是把<strong>游戏与归约</strong>收成方法论：IND-CPA/CCA、EUF-CMA、ROM。不把证明助手课的 Coq 再讲一遍；那是形式核，这里是密码学归约。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Shannon 完善保密不需计算假设。其余原语都有假设：PRP、RSA、LWE。可证明安全：写清敌手能力与获胜条件，给归约。随机预言机模型把哈希当理想黑盒，现实哈希只是近似。缺口是读证明时要问「假设是什么、游戏禁了什么」。</p><h3 id="证明不管实现" tabindex="-1">证明不管实现 <a class="header-anchor" href="#证明不管实现" aria-label="Permalink to &quot;证明不管实现&quot;">​</a></h3><p>归约不管计时、nonce 复用、填充预言。那些在游戏外，误用课收。</p><p><span class="marginnote">GM 1984 语义安全。Bellare–Rogaway 把实践协议游戏化。本课不伪造论文。seL4 更后是系统形式化，对象不同。</span></p><p><span class="marginnote">归约的直觉可以这样说：「假如你有个程序一小时就能伪造签名，我就把它当零件，拼出一个同样快分解大整数的算法」——分解大整数公认做不到，所以伪造签名的程序也不该存在。证明安全从来不是「没人破过」，而是「破了它就等于破了难题」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用 IND-CPA 游戏回顾对称。指出一次一密是信息论，AES-GCM 是计算+nonce 合同。签名用 EUF-CMA。强调具体安全（优势、时间）比渐近一句话有用。</p>',12)),(E(),l(s,null,{default:e(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E5%8D%8F%E8%AE%AE%E6%95%8C%E6%89%8B%22%5D%20--%3E%20RED%5B%22%E5%BD%92%E7%BA%A6%22%5D%0A%20%20RED%20--%3E%20HARD%5B%22%E6%89%93%E7%A0%B4%E5%81%87%E8%AE%BE%E9%97%AE%E9%A2%98%22%5D%0A%20%20GAME%5B%22%E6%B8%B8%E6%88%8F%E5%89%8D%E6%8F%90%22%5D%20--%3E%20ADV%0A%20%20MIS%5B%22%E5%89%8D%E6%8F%90%E5%A4%96%E8%AF%AF%E7%94%A8%22%5D%20-.-%3E%20SIL%5B%22%E8%AF%81%E6%98%8E%E6%B2%89%E9%BB%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"安全进阶的密码学单元到此有语言：完善 vs 计算、游戏、归约、ROM。下一课把常见「证明外失败」列成清单，作为协议单元的入口。",-1)),(E(),l(s,null,{default:e(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E6%95%8C%E6%89%8B%E4%BA%A4%E6%9D%A5%E4%B8%A4%E6%9D%A1%E6%98%8E%E6%96%87%20m0%20%E4%B8%8E%20m1%22%5D%20--%3E%20S2%5B%22%E6%8C%91%E6%88%98%E8%80%85%E6%8E%B7%E7%A1%AC%E5%B8%81%E5%BE%97%20b%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E7%94%A8%E5%AF%86%E9%92%A5%E5%8A%A0%E5%AF%86%20mb%20%E5%8F%91%E5%9B%9E%22%5D%0A%20%20S3%20--%3E%20S4%5B%22%E6%95%8C%E6%89%8B%E4%BB%BB%E6%84%8F%E6%9F%A5%E8%AF%A2%E5%90%8E%E7%8C%9C%20b%20%E6%92%87%22%5D%0A%20%20S4%20--%3E%20S5%7B%22b%20%E6%92%87%20%E7%AD%89%E4%BA%8E%20b%20%3F%22%7D%0A%20%20S5%20--%3E%7C%22%E6%98%AF%22%7C%20W%5B%22%E6%95%8C%E6%89%8B%E8%B5%A2%E4%B8%80%E5%B1%80%22%5D%0A%20%20S5%20--%3E%7C%22%E5%90%A6%22%7C%20L%5B%22%E6%95%8C%E6%89%8B%E8%BE%93%22%5D%0A%20%20W%20-.%E7%BB%9F%E8%AE%A1%E5%A4%A7%E9%87%8F%E5%B1%80%E6%95%B0.-%3E%20ADV%5B%22%E4%BC%98%E5%8A%BF%20%3D%20%E8%B5%A2%E7%9A%84%E9%A2%91%E7%8E%87%20%E5%87%8F%20%E4%BA%8C%E5%88%86%E4%B9%8B%E4%B8%80%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">上图回答「IND-CPA 游戏具体怎么玩」：敌手唯一的目标是从密文里猜出掷硬币结果。方案安全当且仅当任何多项式时间敌手的优势都可忽略——也就是猜对的可能性怎么也甩不开抛硬币的 1/2 太多。</span></p><p><span class="marginnote">初学者容易把「可证明安全」读成「无条件安全」。证明的结论严格绑定游戏写下的前提：密钥不泄、nonce 不复用、随机数真随机。这些前提之外（比如计时侧信道），证明一字不说——那是下一课误用清单的内容。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 GCM 的论文全文。误用清单下一课：从 nonce 到 JWT，全部是合同外。</p><p><span class="marginnote">「具体安全」给个数的感觉：不说「AES-GCM 安全」，而是说「敌手做 \\(2^{128}\\) 次操作前优势不超过 \\(2^{-64}\\)」。工程选型时，这一句能直接换算成「该用多长的密钥、允许打多少次加密询问」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同态等到现在，都该能问：游戏是什么。</li><li>归约连到假设；假设外证明不说话。</li><li>ROM、具体安全、敌手能力都要写进合同。</li><li>下一课：密码学误用清单，然后进入信道。</li><li>出处：Goldwasser and Micali, 1984；Bellare and Rogaway；Katz and Lindell。</li></ul>',7))])}const _=A(p,[["render",c]]);export{S as __pageData,_ as default};
